import type { Page } from "@playwright/test";
import { expect } from "@playwright/test";

export async function fillRegistrationForm(page: Page, email: string) {
  /* ... as before ... */
}

export async function expectSkillAndCountrySelected(
  page: Page,
  skill: string,
  country: string,
) {
  await expect(page.locator("#Skills")).toHaveValue(skill);
  await expect(page.locator("#country")).toHaveValue(country);
}
```

And a spec that uses both:

```ts
import { test } from "@playwright/test";
import { fillRegistrationForm, expectSkillAndCountrySelected } from "./registration-helpers";

test("the chosen skill and country actually stick", async ({ page }) => {
  await fillRegistrationForm(page, "learner.four@example.com");

  await page.locator("#Skills").selectOption({ label: "Java" });
  await page.locator("#country").selectOption("India");

  await expectSkillAndCountrySelected(page, "Java", "India");
});
```

**Note where the `expect` lives.** In [Week 1 - Day 5 - Implementation](/learn/w1/d5/p3) the rule was that page objects never assert. This helper does — and that is not a contradiction, because it is a different kind of helper. Its *name* says it asserts (`expect...`), so a caller reading the spec knows exactly what it does. The rule that matters is not "never assert in a helper"; it is **never hide an assertion inside something that reads like an action**. `fillRegistrationForm` must not assert. `expectSkillAndCountrySelected` must.

> `#country` takes the option **value**, which happens to equal the label here. Where a select's value and label differ, `selectOption({ label: '...' })` is the unambiguous form.
